// Minimal reproduction of the filterByStatus stale cache bug
import { TaskManager } from "../src/task-manager.ts";

const tm = new TaskManager();

// Create initial tasks
tm.createTask({ title: "task1", priority: 1, status: "pending" });
tm.createTask({ title: "task2", priority: 1, status: "completed" });

// Get initial count
let pending = tm.filterByStatus("pending");
console.log("Initial pending count:", pending.length); // Expected: 1

// Add another pending task
tm.createTask({ title: "task3", priority: 1, status: "pending" });
pending = tm.filterByStatus("pending");
console.log("After adding task3, pending count:", pending.length); // Expected: 2, but BUG returns 1

// Test update
const task = pending[0]!;
tm.updateTask(task.id, { status: "completed" });
console.log("After updating task to completed, pending count:", tm.filterByStatus("pending").length); // Expected: 1
console.log("After updating task to completed, completed count:", tm.filterByStatus("completed").length); // Expected: 3

// Check if results are stale
const pendingAfterUpdate = tm.filterByStatus("pending");
const completedAfterUpdate = tm.filterByStatus("completed");
console.log("\nFinal state:");
console.log("Pending:", pendingAfterUpdate.length);
console.log("Completed:", completedAfterUpdate.length);

// Expected: Pending=1, Completed=3 (but BUG might show Pending=2, Completed=2)

